let lang=localStorage.getItem('ralven-lang')||'en',theme=localStorage.getItem('ralven-theme')||'dark',view='overview',noteTab='thesis',page=0,filter='',sector='',rating='',basis='',busy=false,error='',universe={issuers:[]},catalog={companies:[]},coverage=[],c=null,a=null,r=null,mc=null,mcCount=5000,mcSeed=271828,chartRange='1Y',chartMode='comparison',recent=[],forecastMetric=null;
