const tr=(en,id)=>lang==='id'?id:en,fmt=(v,d=0)=>Number.isFinite(v)?v.toLocaleString(lang==='id'?'id-ID':'en-US',{maximumFractionDigits:d}):'—',pct=(v,d=1)=>Number.isFinite(v)?fmt(v*100,d)+'%':'—',rp=v=>Number.isFinite(v)?'Rp '+fmt(v):'—',color=v=>v>0?'positive':v<0?'negative':'muted';
const labels={overview:['Overview','Ringkasan'],financials:['Financials','Keuangan'],valuation:['Valuation','Valuasi'],forecast:['Forecast','Proyeksi'],peers:['Peers','Pembanding'],sensitivity:['Sensitivity','Sensitivitas'],metrics:['Key Metrics','Metrik Utama'],notes:['Notes','Catatan'],screener:['Screener','Penyaring'],integrity:['Model Integrity','Integritas Model'],export:['Research Export','Ekspor Riset'],data:['Company & Data','Emiten & Data'],lab:['Research lab','Pusat riset']};
