function uiIcon(name){const paths={workspace:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',data:'M4 7h16 M4 12h16 M4 17h16 M8 4v16',model:'M4 20V4h16v16H4z M8 8h8 M8 12h2 M14 12h2 M8 16h2 M14 16h2',chart:'M3 17l6-7 4 4 8-10 M3 21h18',peers:'M8 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8z M2 21v-2a6 6 0 0 1 12 0v2 M17 4a4 4 0 0 1 0 8 M17 15a5 5 0 0 1 5 5v1',market:'M3 4h18v13H3z M7 21h10 M12 17v4 M6 12l4-4 3 3 5-4',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',export:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',search:'M21 21l-5-5 M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16',plus:'M12 5v14 M5 12h14',refresh:'M20 7v5h-5 M4 17v-5h5 M6 6a8 8 0 0 1 13 3 M5 15a8 8 0 0 0 13 3',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1',moon:'M21 13a9 9 0 1 1-10-10 7 7 0 0 0 10 10',arrow:'M5 12h14 M13 6l6 6-6 6',settings:'M4 7h16 M4 17h16 M8 3v8 M16 13v8'};return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.chart}"/></svg>`;}
function sectionTitle(title){return (title.charAt(0)+title.slice(1).toLowerCase()).replace(/\b(dcf|ddm|roe|roa|nii|id[r]|idx|pv|pe|pb)\b/g,x=>x.toUpperCase()).replace(/monte carlo/gi,'Monte Carlo');}
function assetStrip(){return tickerStrip(c.mode==='demo'?{}:c,catalog,tickerHistory,{tr,fmt,pct,paused:tickerPaused});}
function recommendationPanel(){const technical=r.engine==='technical',wait=r.recommendation==='WAIT',conditional=r.basis==='INDICATIVE',explain=technical?tr('Price-based signal. No fundamental fair value.','Sinyal berbasis harga. Tanpa nilai wajar fundamental.'):wait?esc((r.decision?.requirements||[])[0]?.[lang==='id'?'id':'en']||tr('Essential evidence is missing. Inspect the required inputs before making a decision.','Bukti penting belum tersedia. Periksa input yang diperlukan sebelum mengambil keputusan.')):r.engine==='residual'?tr('Equity value from book capital and discounted residual earnings.','Nilai ekuitas dari modal buku dan diskonto laba residual.'):r.engine==='relative'?tr('Industry-relative pricing from eligible comparable companies.','Harga relatif industri dari perusahaan pembanding yang layak.'):tr('A blend of eligible intrinsic and relative valuation methods.','Gabungan metode intrinsik dan relatif yang layak.');return `<section class="decision-panel" aria-label="${tr('Investment outlook','Pandangan investasi')}"><div class="decision-heading"><span>${tr('Model outlook','Pandangan model')}</span><span class="decision-kind">${esc(r.decision?.kind||'VALUATION')}</span></div><div class="signal-row"><strong class="signal ${r.recommendation==='BUY'?'positive':r.recommendation==='SELL'?'negative':'accent'}">${esc(r.recommendation)}</strong><span class="assurance-tag">${tr('Assurance','Kepastian')}<b>${esc(r.decision?.confidence||'UNAVAILABLE')}</b></span></div><p class="decision-explain">${explain}</p><div class="fair-value-block"><span>${conditional||wait?tr('Indicative value','Nilai indikatif'):technical?tr('Fundamental value','Nilai fundamental'):tr('Estimated fair value','Estimasi nilai wajar')}</span><strong>${rp(r.fair)}</strong><div class="value-gap ${color(r.upside)}">${Number.isFinite(r.upside)?`${r.upside>=0?'↗':'↘'} ${pct(r.upside)} `+tr('vs market price','vs harga pasar'):tr('Valuation upside unavailable','Potensi valuasi belum tersedia')}</div></div><div class="decision-detail"><span>${tr('Market price','Harga pasar')}</span><b>${rp(c.price)}</b></div><div class="decision-detail"><span>${c.recoveryPlan?tr('Supported range','Rentang didukung'):tr('Bear / bull','Pesimis / optimis')}</span><b>${rp(r.low)} / ${rp(r.high)}</b></div><div class="decision-detail"><span>${tr('Financial basis','Basis keuangan')}</span><b>${esc(c.periodBasis||'ANNUAL')} · ${esc(c.period||'—')}</b></div><div class="quality-summary ${wait?'blocked':''}"><span class="quality-dot"></span><div><b>${wait?tr('Action required','Perlu tindakan'):technical?tr('Technical signal only','Sinyal teknikal saja'):c.mode==='demo'?tr('Synthetic example','Contoh sintetis'):conditional?tr('Conditional valuation','Valuasi bersyarat'):tr('Source checks passed','Pemeriksaan sumber lolos')}</b><small>${wait?esc((r.decision?.requirements||[])[0]?.[lang==='id'?'id':'en']||explain):technical?tr('Use alongside fundamental research.','Gunakan bersama riset fundamental.'):c.mode==='demo'?tr('Fictional inputs; use only to inspect model behavior.','Input fiktif; hanya untuk memeriksa perilaku model.'):conditional?tr('Read the method assumptions and limitations.','Baca asumsi dan keterbatasan metode.'):`${r.quality?.verified||0}/${r.quality?.total||0} `+tr('used inputs have primary or corroborating evidence.','input terpakai memiliki bukti primer atau pendukung.')}</small></div></div><button class="primary-action" data-view="${wait?'integrity':'valuation'}">${uiIcon(wait?'shield':'settings')}${wait?tr('View requirements','Lihat persyaratan'):tr('Edit assumptions','Ubah asumsi')}${uiIcon('arrow')}</button><button class="secondary-action" data-action="pdf">${uiIcon('export')}${tr('Download report','Unduh laporan')}</button><div class="decision-links"><button data-view="integrity">${tr('Inspect evidence','Periksa bukti')}</button><details><summary>${tr('Rating rules','Aturan rating')}</summary><p>${decisionCriteria()}</p></details></div></section>`;}
function chartWorkspace(){const change=c.previousClose>0?c.price/c.previousClose-1:null;return `<section class="chart-panel"><div class="chart-panel-head"><div><span class="eyebrow">${tr('Market overview','Ringkasan pasar')}</span><div class="chart-quote">${rp(c.price)} <span class="change-pill ${color(change)}">${Number.isFinite(change)?(change>0?'+':'')+pct(change):'—'}</span></div><small>${tr('Observed close','Penutupan teramati')} · ${esc(c.priceDate||'—')} · IDR</small></div><button class="icon-button" data-action="refresh" aria-label="${tr('Refresh issuer data','Perbarui data emiten')}">${uiIcon('refresh')}</button></div><div class="chart-toolbar"><div class="segmented chart-modes">${[['comparison',tr('Price & value','Harga & nilai')],['market',tr('Market price','Harga pasar')]].map(([key,text])=>`<button data-chart-mode="${key}" aria-pressed="${chartMode===key}" class="${chartMode===key?'active':''}">${text}</button>`).join('')}</div><div class="range-buttons">${['1M','3M','6M','1Y'].map(x=>`<button data-range="${x}" aria-pressed="${chartRange===x}" class="${chartRange===x?'active':''}">${x}</button>`).join('')}</div></div>${priceChart()}<div class="chart-bottom"><span>${uiIcon('chart')}${tr('Historical closing prices','Riwayat harga penutupan')}</span><button data-view="sensitivity">${tr('Explore scenarios','Jelajahi skenario')} ${uiIcon('arrow')}</button></div></section>`;}
function notify(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').style.display='none',6000);}
function recalc(){r=analyzeCompany(c,a);mc=simulate(c,a,r,{...mcConfig,count:mcCount,seed:mcSeed});}
function setCompany(raw,params,{historical=false}={}){const previous=c?{company:c,result:r}:null,prepared=raw.mode==='demo'?raw:prepareEvidence(raw);c={...prepared,peerUniverse:raw.peerUniverse||raw.peers||[],excludedPeerTickers:raw.excludedPeerTickers||issuerStateFor(raw.ticker).exclusions||[]};c.peers=selectPeers({...c,peers:c.peerUniverse});if(c.mode!=='demo'&&!historical)c.valuationDate=valuationDateToday();a=params||assumptions(c);const savedRecovery=issuerStateFor(c.ticker);if(!historical&&!raw.recoveryPlan&&savedRecovery.recoveryPlan){c.recoveryPlan=structuredClone(savedRecovery.recoveryPlan);if(savedRecovery.recoveryPaths)a.paths=structuredClone(savedRecovery.recoveryPaths);}recalc();registerStatementSnapshot(c.ticker,c.statementArchive,c.snapshotId);issuerState().changes=changeBridge(previous,{company:c,result:r});recent=[{ticker:c.ticker,name:c.name},...recent.filter(x=>x.ticker!==c.ticker)].slice(0,6);localStorage.setItem('ralven-recent',JSON.stringify(recent));if(c.mode==='live')updateCoverage(c);const watch=researchState.watchlist.find(x=>x.ticker===c.ticker);if(watch){watch.alert=watch.period!==c.period?'New financial basis: '+c.period:watch.snapshotId!==c.snapshotId?'Source snapshot changed':'';watch.period=c.period;watch.snapshotId=c.snapshotId;}persistResearch();}
function issuerStateFor(ticker){return researchState.byIssuer[ticker]??={scenarios:{},notes:[],snapshots:[]};}
function updateCoverage(subject){const all=[subject,...subject.peerUniverse||subject.peers||[]];for(const fresh of all){const index=catalog.companies.findIndex(p=>p.ticker===fresh.ticker);if(index>=0)catalog.companies[index]={...fresh,peers:[]};else catalog.companies.push({...fresh,peers:[]});}const affected=new Set(all.map(x=>x.ticker));for(const item of all){const raw={...item,valuationDate:valuationDateToday(),excludedPeerTickers:[],peers:selectPeers(item,catalog.companies.filter(p=>p.evidence))};const row=coverageRows({issuers:universe.issuers.filter(x=>x.ticker===item.ticker)},{companies:[...catalog.companies.filter(x=>x.evidence),raw]});const index=coverage.findIndex(x=>x.ticker===item.ticker);if(row[0]){row[0].snapshotId=item.snapshotId||subject.snapshotId;row[0].volume=item.volume;index>=0?coverage[index]=row[0]:coverage.push(row[0]);}}for(const row of coverage)if(!affected.has(row.ticker)&&row.industry===subject.industry)row.dependencyStatus='Peer refresh available; open to rescreen';}

async function load(ticker){if(busy)return;ticker=String(ticker||'').trim().toUpperCase().replace(/\.JK$/,'');if(!universe.issuers.some(x=>x.ticker===ticker)){notify(tr('Select an issuer from the IDX directory or import a documented new listing.','Pilih emiten dalam direktori BEI atau impor pencatatan baru bersumber.'));return;}busy=true;error='';render();try{const data=await getJSON('/api/company/'+encodeURIComponent(ticker)+'?refresh=1');setCompany(data);view='overview';}catch(e){try{setCompany(await getJSON('/api/snapshot/'+ticker));view='overview';error=tr('Live update unavailable. Source snapshot dates are retained.','Pembaruan langsung belum tersedia. Tanggal snapshot sumber dipertahankan.');}catch{error=e.message;}}finally{busy=false;render();}}

function table(headers,rows,classes=''){return `<div class="table-wrap"><table class="${classes}"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr class="${row.class||''}">${(row.cells||row).map(x=>`<td>${x??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function panel(n,title,body,span=4,extra=''){return `<section class="panel span${span}" data-panel="${n}"><div class="panel-h"><span>${sectionTitle(title)}</span>${extra}</div><div class="panel-body">${body}</div></section>`;}
function kpi(title,value,cls='',sub=''){return `<div class="kpi"><div class="klabel">${title}</div><div class="kvalue ${cls}">${value}</div>${sub?`<sub>${sub}</sub>`:''}</div>`;}
const empty=s=>`<div class="empty">${s}</div>`;
function spark(values,stroke='var(--blue)'){values=values.filter(Number.isFinite);if(values.length<2)return `<span class="muted">—</span>`;const lo=Math.min(...values),hi=Math.max(...values),d=hi-lo||1,points=values.map((v,i)=>`${2+i/(values.length-1)*80},${18-(v-lo)/d*16}`).join(' ');return `<svg class="spark" viewBox="0 0 85 20" aria-label="${tr('Historical trend','Tren historis')}"><polyline fill="none" stroke="${stroke}" stroke-width="1.5" points="${points}"/></svg>`;}
function decisionCriteria(){return r.engine==='technical'?tr('Technical BUY: price > SMA50, 63-session momentum >5%, RSI14 <75. SELL: price < SMA50 and momentum <−5%; otherwise HOLD. No fair value is inferred.','BUY teknikal: harga > SMA50, momentum 63 sesi >5%, RSI14 <75. SELL: harga < SMA50 dan momentum <−5%; lainnya HOLD. Tanpa estimasi nilai wajar.'):tr('Valuation thresholds: ','Ambang valuasi: ')+`BUY ≥ ${pct(a.buy,0)} · SELL ≤ ${pct(a.sell,0)} · HOLD `+tr('between thresholds. WAIT: resolve required data or input issues.','di antara ambang. WAIT: selesaikan kendala data/input.');}
function summary(){return `<div class="kpis">${kpi(r.basis==='FUNDAMENTAL'||c.mode==='demo'?tr('Fair Value (Central)','Nilai Wajar (Pusat)'):tr('Indicative Value','Nilai Indikatif'),rp(r.fair),r.basis==='FUNDAMENTAL'?'positive':'accent')}${kpi(tr('Upside / Downside','Potensi Naik / Turun'),pct(r.upside),color(r.upside))}${kpi(r.engine==='technical'?tr('Technical Signal','Sinyal Teknikal'):tr('Recommendation','Rekomendasi'),r.recommendation,r.recommendation==='BUY'?'positive':r.recommendation==='SELL'?'negative':'accent',esc(r.basis)+' · '+tr('assurance','kepastian')+' '+esc(r.decision?.confidence||'—'))}${kpi(tr('Verified Inputs','Input Terverifikasi'),(r.quality?.verified||0)+'/'+(r.quality?.total||0),'small',r.engine==='technical'?tr('price history only','hanya riwayat harga'):tr('method evidence · view sources','bukti metode · lihat sumber'))}</div><div class="mini-kpis">${kpi(tr('Market Price','Harga Pasar'),rp(c.price))}${kpi(r.engine==='residual'?tr('Residual Income','Residual Income'):financial(c)?'DDM':'DCF',r.engine==='residual'?rp(r.residual.price):r.eligible?rp(r.dcf?.price):'—')}${kpi(tr('Relative Value','Nilai Relatif'),rp(r.relative.price))}${kpi(tr('Bear Case','Pesimis'),rp(c.recoveryPlan?r.scenarios.bear:r.low),'negative')}${kpi(tr('Bull Case','Optimis'),rp(c.recoveryPlan?r.scenarios.bull:r.high),'positive')}</div><div class="caption">${decisionCriteria()}</div>`;}
function priceChart(){const full=c.prices||[],rows=chartRange==='1M'?full.slice(-22):chartRange==='3M'?full.slice(-63):chartRange==='6M'?full.slice(-126):full;if(!rows.length)return empty(tr('Observed price history unavailable. Refresh the feed.','Riwayat harga tidak tersedia. Perbarui data.'));const compare=chartMode==='comparison',vals=[...rows.map(x=>x.close),...(compare?[r.low,r.fair,r.high]:[])].filter(Number.isFinite),min=Math.min(...vals)*.92,max=Math.max(...vals)*1.06,W=innerWidth>1000?Math.max(480,document.documentElement.clientWidth-(innerWidth>=1600?532:innerWidth>1250?490:430)):innerWidth<680?480:920,H=innerWidth>=1600?290:innerWidth>1000?270:innerWidth<680?290:330,L=innerWidth<680?48:62,R=innerWidth<680?72:100,T=22,B=34,x=i=>L+i/Math.max(1,rows.length-1)*(W-L-R),y=v=>T+(max-v)/(max-min||1)*(H-T-B),path=rows.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(p.close).toFixed(1)}`).join(' ');let svg='';for(let i=0;i<5;i++){const v=min+(max-min)*i/4;svg+=`<line class="gridline" x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}"/><text x="${L-7}" y="${y(v)+4}" text-anchor="end">${fmt(v)}</text>`;}if(r.valid&&compare)svg+=`<rect x="${L}" y="${y(r.high)}" width="${W-L-R}" height="${Math.max(0,y(r.low)-y(r.high))}" fill="var(--blue)" opacity=".08"/>`;
 let labelY=T-16;for(const [name,value,col] of [[tr('Bull','Opt.'),r.high,'var(--green)'],[tr('Base','Dsr.'),r.fair,'var(--blue)'],[tr('Bear','Pes.'),r.low,'var(--red)']])if(compare&&Number.isFinite(value)){const target=Math.max(labelY+16,Math.min(H-B-34,y(value)));labelY=target;svg+=`<line x1="${L}" x2="${W-R}" y1="${y(value)}" y2="${y(value)}" stroke="${col}" stroke-dasharray="5 4" opacity=".8"/><path d="M${W-R},${y(value)} L${W-R+5},${target} L${W-R+8},${target}" fill="none" stroke="${col}"/><text x="${W-R+10}" y="${target+4}" style="fill:${col};font-size:10px">${name} ${fmt(value)}</text>`;}
 for(let i=0;i<=4;i++){const index=Math.round((rows.length-1)*i/4);svg+=`<text x="${x(index)}" y="${H-4}" text-anchor="middle">${esc(chartRange==='1M'||chartRange==='3M'?rows[index].date.slice(5):rows[index].date.slice(0,7))}</text>`;}return `<div class="legend"><span><i class="dot"></i>${tr('Observed market price','Harga pasar teramati')}</span>${compare?`<span><i class="dot" style="background:var(--blue)"></i>${tr('Model value range','Rentang nilai model')}</span>`:''}</div><svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${compare?tr('Observed market prices against current fair values','Harga pasar dan nilai wajar kini'):tr('Observed market price history','Riwayat harga pasar teramati')}">${svg}<path d="${path}" fill="none" stroke="var(--green)" stroke-width="2.2"/></svg><div class="caption">${compare?tr('Fair values are today’s model outputs, held constant for comparison. No historical fair values are implied.','Nilai wajar adalah hasil model kini, ditampilkan konstan sebagai pembanding; bukan nilai wajar historis.'):tr('Observed closing prices in IDR. Source dates are retained; this is not a live trading feed.','Harga penutupan teramati dalam IDR. Tanggal sumber dipertahankan; bukan feed perdagangan langsung.')}</div>`;}
function breakdown(){const d=r.engine==='residual'?r.residual.price:r.eligible?r.dcf?.price:null;return table([tr('Method','Metode'),tr('Fair (Rp)','Wajar (Rp)'),tr('Weight','Bobot'),tr('Weighted Rp','Tertimbang Rp')],[[r.engine==='residual'?'Residual income · ROE fade':financial(c)?'DDM · Gordon Growth':'DCF · FCFF',rp(d),d!==null?pct(r.weight,0):'—',d!==null?rp(d*r.weight):'—'],[r.relative.legs.map(x=>x.metric.toUpperCase()).join(' / ')||tr('Relative valuation','Valuasi relatif'),rp(r.relative.price),r.relative.price?pct(1-r.weight,0):'—',r.relative.price?rp(r.relative.price*(1-r.weight)):'—'],{class:'total',cells:[tr('Central Fair Value','Nilai Wajar Pusat'),rp(r.fair),r.valid?'100%':'—',rp(r.fair)]}])+`<details class="method-notes"><summary>${tr('Method notes & limitations','Catatan metode & keterbatasan')}</summary><p>${esc(r.rationale)}</p></details>`;}
function residualTable(){return table(['IDR bn',...r.residual.rows.map(x=>'Y'+x.year)],[['openingBook',tr('Opening equity','Ekuitas awal')],['roe','ROE'],['netIncome',tr('Earnings','Laba')],['dividend',tr('Dividends','Dividen')],['charge',tr('Equity charge','Beban ekuitas')],['excess',tr('Residual income','Laba residual')],['pv','PV'],['closingBook',tr('Closing equity','Ekuitas akhir')]].map(([k,l])=>[l,...r.residual.rows.map(x=>k==='roe'?pct(x[k]):fmt(x[k]))]))+`<div class="caption">${tr('Five-year clean-surplus equity forecast. ROE fades to Ke; no terminal excess income.','Proyeksi ekuitas surplus bersih lima tahun. ROE turun ke Ke; tanpa laba residual terminal.')}</div>`;}
function residualBridge(){const d=r.residual;return table([tr('Equity bridge','Rekonsiliasi ekuitas'),'IDR bn'],[[tr('Opening parent equity','Ekuitas induk awal'),fmt(d.bookValue)],[tr('PV residual income','PV laba residual'),fmt(d.pvExcess)],[tr('Equity value','Nilai ekuitas'),fmt(d.equity)],[tr('Shares bn','Saham miliar'),fmt(c.shares,4)],[tr('IDR / share','IDR / saham'),fmt(d.price)]])+`<div class="caption">${esc(r.rationale)}</div>`;}
function financialTable(forecastOnly=false){if(forecastOnly&&r.residual)return residualTable();const hs=(c.history||[]).slice(-3),fs=r.dcf?.rows||[],cols=forecastOnly?fs:fs.slice(0,2),heads=[tr('Metric / IDR bn','Metrik / miliar IDR'),...(!forecastOnly?hs.map(h=>h.basis==='TTM'?esc(h.period)+' TTM':esc(h.year)+'A'):[]),...cols.map(x=>(x.periodEnd||('Y'+x.year))+' F')];const keys=financial(c)?[['netInterestIncome',tr('Net interest income','Pendapatan bunga bersih')],['netIncome',tr('Net income','Laba bersih')],['bookEquity',tr('Book equity','Ekuitas buku')],['ocf',tr('Operating CF','Arus kas operasi')]]:[['revenue',tr('Revenue','Pendapatan')],['ebit','EBIT'],['netIncome',tr('Net income','Laba bersih')],['ocf',tr('Operating CF','Arus kas operasi')]];return table(heads,keys.map(([key,title])=>[title,...(!forecastOnly?hs.map(h=>fmt(h[key])):[]),...cols.map(h=>key==='netIncome'&&!financial(c)?'—':key==='netInterestIncome'? '—':fmt(h[key]))]))+`<div class="caption">A = ${tr('annual actual','aktual tahunan')} · F = ${tr('analyst forecast','proyeksi analis')}. ${r.engine==='residual'?tr('Residual-income earnings and equity forecasts are in the Forecast tab.','Proyeksi laba dan ekuitas residual income ada di tab Proyeksi.'):!financial(c)?tr('FCFF model does not project corporate net income.','Model FCFF tidak memproyeksikan laba bersih korporasi.'):tr('DDM forecasts earnings and dividends; regulatory ratios require issuer filings.','DDM memproyeksikan laba dan dividen; rasio regulasi perlu laporan emiten.')}</div>`;}
function metrics(){const history=c.history||[],annual=history.filter(h=>h.basis!=='TTM'),prev=annual.at(-2),ttm=c.periodBasis==='TTM',bank=financial(c),revenueKey=bank?'netInterestIncome':'revenue',denominator=bank?c.netInterestIncome:c.revenue;const avg=key=>ttm?c[key]>0?c[key]:null:c[key]>0&&prev?.[key]>0?(c[key]+prev[key])/2:null;
 let growth=null;if(ttm){const current=(c.observations||[]).find(o=>o.sourceType==='primary'&&o.field===revenueKey&&o.period===c.period&&o.duration>0&&o.duration<350),prior=current&&(c.observations||[]).find(o=>o.sourceType==='primary'&&o.field===revenueKey&&o.period===(Number(c.period.slice(0,4))-1)+c.period.slice(4)&&Math.abs(o.duration-current.duration)<=1&&o.currency===current.currency&&o.unit===current.unit);if(current&&prior?.value>0)growth=current.value/prior.value-1;}else if(prev?.[revenueKey]>0)growth=denominator/prev[revenueKey]-1;
 const ratio=(n,d)=>Number.isFinite(n)&&d>0?n/d:null;const rows=[[ttm?tr('ROE (closing equity)','ROE (ekuitas akhir)'):tr('ROE (avg. equity)','ROE (ekuitas rata-rata)'),ratio(c.netIncome,avg('bookEquity')),annual.map(h=>ratio(h.netIncome,h.bookEquity))],[bank?tr('Profit / NII','Laba / NII'):tr('Net margin','Margin bersih'),ratio(c.netIncome,denominator),annual.map(h=>ratio(h.netIncome,h[revenueKey]))],[bank?(ttm?tr('NII growth · YTD YoY','Pertumbuhan NII · YTD YoY'):tr('NII growth','Pertumbuhan NII')):(ttm?tr('Sales growth · YTD YoY','Pertumbuhan penjualan · YTD YoY'):tr('Revenue growth','Pertumbuhan pendapatan')),growth,annual.map((h,i)=>i&&annual[i-1][revenueKey]>0?h[revenueKey]/annual[i-1][revenueKey]-1:null)],[bank?(ttm?tr('ROA (closing assets)','ROA (aset akhir)'):tr('ROA (avg. assets)','ROA (aset rata-rata)')):tr('EBIT margin','Margin EBIT'),bank?ratio(c.netIncome,avg('assets')):ratio(c.ebit,c.revenue),annual.map(h=>bank?ratio(h.netIncome,h.assets):ratio(h.ebit,h.revenue))]];return rows.map(([title,value,hs])=>`<div class="metric"><span>${title}</span><b class="${color(value)}" style="text-align:right">${pct(value)}</b>${spark(hs)}</div>`).join('')+`<div class="metric"><span>P/E</span><b style="text-align:right">${c.netIncome>0?fmt(c.price*c.shares/c.netIncome,1)+'x':'—'}</b>${spark(annual.map(h=>h.netIncome))}</div><div class="metric"><span>P/B</span><b style="text-align:right">${c.bookEquity>0?fmt(c.price*c.shares/c.bookEquity,1)+'x':'—'}</b>${spark(annual.map(h=>h.bookEquity))}</div><div class="caption">${tr('TTM returns use closing balances when matching prior-year balances are unavailable. Growth compares like-for-like YTD periods. Sparklines show annual financial trends, not historical trading multiples.','Imbal hasil TTM memakai saldo akhir bila saldo tahun sebelumnya tidak tersedia. Pertumbuhan membandingkan YTD sepadan. Sparkline menunjukkan tren keuangan tahunan, bukan kelipatan pasar historis.')}</div>`;}

const multipleLabel=k=>({pe:'P/E',pb:'P/B',evEbitda:'EV/EBITDA',evSales:'EV/Sales'})[k]||k;
function peerRatio(p,key){if(!(p.price>0&&p.shares>0))return null;const mc=p.price*p.shares;if(key==='pe')return p.netIncome>0?mc/p.netIncome:null;if(key==='pb')return p.bookEquity>0?mc/p.bookEquity:null;if(!['debt','cash','minority','preferred'].every(k=>Number.isFinite(p[k])&&p[k]>=0))return null;const denominator=key==='evSales'?p.revenue:p.ebitda;return denominator>0?(mc+p.debt-p.cash+p.minority+p.preferred)/denominator:null;}
function peerEligibility(p,key){const ratio=peerRatio(p,key),cap=key==='pb'?20:key==='evSales'?30:100;if(!(r.relative.peers||[]).some(x=>x.ticker===p.ticker))return {ok:false,text:tr('Data screen','Saringan data')};if(ratio===null)return {ok:false,text:key==='pe'&&Number.isFinite(p.netIncome)&&p.netIncome<=0?tr('Loss / zero NI','Rugi / laba nol'):tr('Missing / invalid','Kosong / tidak valid')};if(ratio<=0)return {ok:false,text:tr('Nonpositive','Nonpositif')};if(ratio>=cap)return {ok:false,text:`≥ ${cap}x`};return {ok:true,text:tr('Included','Digunakan')};}
function peerCaveats(){const peers=c.peers||[],notes=[];const revenues=peers.map(p=>p.revenue).filter(v=>Number.isFinite(v)&&v>0);if(c.revenue>0&&revenues.length&&Math.max(...revenues)/c.revenue<.1)notes.push(tr(`Scale mismatch: the largest selected peer has ${pct(Math.max(...revenues)/c.revenue)} of the subject's revenue. Review comparability before relying on the relative estimate.`,`Perbedaan skala: pendapatan pembanding terbesar hanya ${pct(Math.max(...revenues)/c.revenue)} dari emiten. Tinjau kesebandingan sebelum memakai estimasi relatif.`));if(c.subIndustry&&peers.length&&!peers.some(p=>p.subIndustry===c.subIndustry))notes.push(tr('No selected peer has the same IDX sub-industry. Industry matching alone does not establish business comparability.','Tidak ada pembanding dengan subindustri BEI yang sama. Kesamaan industri belum membuktikan kesebandingan bisnis.'));if(r.eligible&&r.relative.price>0&&r.dcf?.price>0&&Math.max(r.relative.price,r.dcf.price)/Math.min(r.relative.price,r.dcf.price)>2)notes.push(tr('The relative and intrinsic estimates differ by more than 2×. Reconcile earnings, capital claims and peer business mix before using the blend.','Estimasi relatif dan intrinsik berbeda lebih dari 2×. Rekonsiliasi laba, klaim modal, dan bisnis pembanding sebelum memakai nilai gabungan.'));return notes.length?`<div class="peer-note"><b class="accent">${tr('COMPARABILITY REVIEW','TINJAUAN KESEBANDINGAN')}</b>${notes.map(n=>`<p>${esc(n)}</p>`).join('')}</div>`:'';}
function peerTable(detailed=false){const peers=detailed?(c.peers||[]):r.relative.peers||c.peers||[],subject={...c},metrics=r.relative.legs.length?r.relative.legs.map(x=>x.metric):financial(c)?['pe','pb']:['pe','evEbitda'];const headers=detailed?[tr('Company / business','Emiten / bisnis'),tr('Revenue · IDR bn','Pendapatan · miliar IDR'),...metrics.flatMap(k=>[multipleLabel(k)+' x',tr('Eligibility','Kelayakan')]),tr('Fiscal period','Periode laporan')]:[tr('Company','Emiten'),'P/E x','P/B x',financial(c)?'ROE*':'EV/EBITDA x',tr('Revenue','Pendapatan'),tr('FY','TA')];const rows=[subject,...(detailed?peers:peers.slice(0,7))].map((p,i)=>({class:i===0?'subject':'',cells:detailed?[`<b>${esc(p.ticker)}</b><span class="peer-business">${esc(p.subIndustry||p.industry||p.sector)}</span>`,fmt(p.revenue),...metrics.flatMap(k=>{const status=peerEligibility(p,k);return [fmt(peerRatio(p,k),2),i===0?`<span class="peer-status blue">${tr('SUBJECT','SUBJEK')}</span>`:`<span class="peer-status ${status.ok?'positive':'accent'}">${esc(status.text)}</span>`];}),esc(p.period||'—')]:[`<b>${esc(p.ticker)}</b>`,fmt(peerRatio(p,'pe'),1),fmt(peerRatio(p,'pb'),1),financial(c)?pct(p.bookEquity>0&&Number.isFinite(p.netIncome)?p.netIncome/p.bookEquity:null):fmt(peerRatio(p,'evEbitda'),1),fmt(p.revenue),esc(p.period||'—')]}));return table(headers,rows,detailed?'peer-detail':'')+`<div class="caption">${tr('Up to 12 industry peers, ranked by subindustry and market-cap similarity. Annual/TTM end dates within 100 days; quotes within 7 days. Min. 3 eligible observations per multiple. Caps: P/E and EV/EBITDA <100x; P/B <20x; EV/Sales <30x.','Maks. 12 pembanding industri, urut subindustri dan kemiripan kapitalisasi. Akhir tahunan/TTM berselisih maksimal 100 hari; harga maksimal 7 hari. Min. 3 observasi layak per kelipatan. Batas: P/E dan EV/EBITDA <100x; P/B <20x; EV/Sales <30x.')} ${!detailed&&financial(c)?tr('*ROE uses closing equity here.','*ROE memakai ekuitas akhir.'):''}</div>${detailed?peerCaveats():''}`;}
function relativeBridge(){const rows=r.relative.legs.map(x=>{const used=x.price>0;let reason=x.count<3?`${x.count} / 3 ${tr('peers','pembanding')}`:tr('Subject / bridge ineligible','Subjek / rekonsiliasi tidak layak');return [multipleLabel(x.metric),fmt(x.multiple,2),x.count,`<span class="peer-status ${used?'positive':'accent'}">${used?tr('USED','DIGUNAKAN'):tr('EXCLUDED','DIKECUALIKAN')}</span>`,used?rp(x.price):`<span class="muted">${reason}</span>`];});let html=table([tr('Multiple','Kelipatan'),tr('Median','Median'),'N',tr('Status','Status'),tr('Implied Rp','Rp tersirat')],rows)+`<div class="caption">${tr('A displayed median is not used when fewer than three peers qualify. Only eligible implied prices enter the relative estimate.','Median yang ditampilkan tidak digunakan jika pembanding layak kurang dari tiga. Hanya harga tersirat yang layak masuk estimasi relatif.')}</div>`;for(const leg of r.relative.legs.filter(x=>x.price>0)){const evBased=leg.metric==='evEbitda'||leg.metric==='evSales',denominator=leg.metric==='pe'?c.netIncome:leg.metric==='pb'?c.bookEquity:leg.metric==='evSales'?c.revenue:c.ebitda,name=leg.metric==='pe'?tr('Net income','Laba bersih'):leg.metric==='pb'?tr('Book equity','Ekuitas buku'):leg.metric==='evSales'?tr('Revenue','Pendapatan'):'EBITDA',implied=leg.multiple*denominator;html+=`<div class="relative-formula">${multipleLabel(leg.metric)}: ${evBased?'EV':'Equity'} = ${fmt(leg.multiple,2)} × ${esc(name)}<br>${evBased?tr('Equity = EV + cash − debt − NCI − preferred','Ekuitas = EV + kas − utang − KNP − preferen')+'<br>':''}${tr('IDR/share = equity ÷ shares','IDR/saham = ekuitas ÷ saham')}</div>`+table([tr('Reconciliation · IDR bn','Rekonsiliasi · miliar IDR'),tr('Value','Nilai')],[[esc(name),fmt(denominator)],[evBased?tr('Implied enterprise value','Nilai perusahaan tersirat'):tr('Implied equity value','Nilai ekuitas tersirat'),fmt(implied)],...(evBased?[[tr('+ Cash','+ Kas'),fmt(c.cash)],[tr('− Debt','− Utang'),fmt(c.debt)],[tr('− NCI / preferred','− KNP / preferen'),fmt(c.minority+c.preferred)]]:[]),[tr('Shares · bn','Saham · miliar'),fmt(c.shares,3)],{class:'total',cells:[tr('Implied price · IDR','Harga tersirat · IDR'),rp(leg.price)]}],'bridge-table');}return html+`<div class="caption">${esc(r.rationale)}</div>`;}
function dcfSummary(){if(!r.dcf&&!r.residual)return table([tr('Scenario','Skenario'),tr('Value / share','Nilai / saham')],Object.entries(r.scenarios).map(([k,v])=>[esc(k),rp(v)]))+`<div class="caption">${r.engine==='technical'?decisionCriteria():esc(r.rationale)}</div>`;if(r.residual)return table([tr('Equity model','Model ekuitas'),tr('Value','Nilai')],[[tr('Starting ROE','ROE awal'),pct(r.residual.initialRoe)],[tr('Cost of equity','Biaya ekuitas'),pct(r.residual.ke)],[tr('Payout','Dividen'),pct(a.payout)],[tr('Fade horizon','Periode penurunan'),'5Y'],[tr('Terminal excess return','Imbal hasil berlebih terminal'),'0'],[tr('Base / bear / bull','Dasar / pesimis / optimis'),[r.fair,r.low,r.high].map(rp).join(' / ')]])+`<div class="caption">${tr('Bear: starting ROE −20%, Ke +1pp. Bull: ROE +20%, Ke −1pp. Book growth follows retained earnings.','Pesimis: ROE awal −20%, Ke +1pp. Optimis: ROE +20%, Ke −1pp. Pertumbuhan buku mengikuti laba ditahan.')}</div>`;return table([tr('Assumption','Asumsi'),tr('Base','Dasar'),tr('Bear','Pesimis'),tr('Bull','Optimis')],[[tr('Forecast period','Periode proyeksi'),'5Y','5Y','5Y'],[tr('Y1 growth','Pertumbuhan Y1'),pct(a.paths?.[0]?.growth??a.growth),pct((a.paths?.[0]?.growth??a.growth)-.03),pct((a.paths?.[0]?.growth??a.growth)+.03)],[tr('Terminal growth','Pertumbuhan terminal'),pct(a.g),pct(a.g),pct(a.g)],[financial(c)?tr('Cost of equity','Biaya ekuitas'):'WACC',pct(r.dcf?.wacc),r.dcf?pct(capital(c,{...a,rf:a.rf+.01}).wacc):'—',r.dcf?pct(capital(c,{...a,rf:Math.max(0,a.rf-.01)}).wacc):'—'],{class:'total',cells:[tr('Fair value (Rp)','Nilai wajar (Rp)'),fmt(r.fair),`<span class="negative">${fmt(c.recoveryPlan?r.scenarios.bear:r.low)}</span>`,`<span class="positive">${fmt(c.recoveryPlan?r.scenarios.bull:r.high)}</span>`]}])+`<div class="caption">${c.recoveryPlan?tr('Recovery scenarios failing liquidity or terminal checks are omitted; the supported range contains only accepted cases. Annual paths receive the same driver shocks. ','Skenario pemulihan yang gagal uji likuiditas atau terminal dihilangkan; rentang didukung hanya mencakup kasus yang diterima. Jalur tahunan menerima stres penggerak yang sama. '):''}${r.engine==='core'?tr('Bear/bull: growth ∓3pp, operating margin ∓2.5pp (corporates), risk-free rate ±1pp. Corporate WACC shift reflects equity weight. Peer multiples ∓20%; EV-to-equity bridge recomputed.','Pesimis/optimis: pertumbuhan ∓3pp, margin ∓2,5pp (korporasi), bebas risiko ±1pp. Perubahan WACC mengikuti bobot ekuitas. Kelipatan ∓20%; rekonsiliasi EV ke ekuitas dihitung ulang.'):esc(r.rationale)}</div>`;}
function analysisEmpty(){return empty(esc(tr(analysisUnavailable(c,r)||'No supported analysis.','Analisis belum didukung. ')+(lang==='id'?(r.decision?.requirements||[]).map(x=>x.id).join(' '):'')))+`<button class="secondary-action" data-view="integrity">${tr('Inspect missing inputs','Periksa input yang kurang')} ↗</button>`;}
function heatmap(){const m=sensitivityMatrix(c,a,r);if(!m.available)return analysisEmpty();const names={'Cost of equity':['Cost of equity','Biaya ekuitas'],'Starting ROE':['Starting ROE','ROE awal'],'Subject denominators':['Subject denominators','Penyebut emiten'],'Peer multiples':['Peer multiples','Kelipatan pembanding'],'Terminal growth':['Terminal growth','Pertumbuhan terminal'],WACC:['WACC','WACC']};const axis=x=>tr(...names[x]);return `<div class="caption">${axis(m.rowLabel)} ↓ / ${axis(m.columnLabel)} → · IDR/share</div>`+table([axis(m.rowLabel),...m.columnValues.map(v=>m.kind==='relative'?fmt(v,2)+'×':pct(v))],m.values.map((row,i)=>[m.kind==='relative'?fmt(m.rowValues[i],2)+'×':pct(m.rowValues[i]),...row.map((v,j)=>{if(!Number.isFinite(v))return '—';const x=v/c.price-1,alpha=Math.min(.45,Math.abs(x)*.4+.07);return `<span class="sensitivity-cell ${i===2&&j===2?'base-cell':''}" style="background:${x>=0?`rgb(0 151 120 / ${alpha})`:`rgb(181 43 64 / ${alpha})`}">${fmt(v)}</span>`;})]),'heat')+`<div class="caption">${esc(tr(m.description,m.kind==='relative'?'Nilai relatif IDR/saham. Kelipatan dan penyebut sepadan digeser; klaim modal dan saham tetap. Bukan perubahan proyeksi.':m.kind==='residual'?'Nilai residual income IDR/saham. ROE turun ke biaya ekuitas selama lima tahun; dividen dan modal awal tetap.':'Nilai gabungan IDR/saham; bobot metode serta nilai relatif tetap. Kombinasi tidak valid dihilangkan.'))} ${tr('Outlined cell = base case.','Sel bergaris = skenario dasar.')}</div>`;}
function driverChart(){const rows=tornado(c,a,r);if(!rows.length)return analysisEmpty();const max=Math.max(1e-9,...rows.map(x=>x.impact)),height=rows.length*32+42;return `<svg class="chart tornado-chart" style="height:${height}px" viewBox="0 0 520 ${height}" role="img" aria-label="${tr('Valuation driver sensitivity','Sensitivitas pendorong valuasi')}"><line x1="335" x2="335" y1="8" y2="${height-30}" stroke="var(--muted)"/>${rows.map((row,i)=>{const y=12+i*32,lo=Number.isFinite(row.low)?(row.low-r.fair)/max*120:0,hi=Number.isFinite(row.high)?(row.high-r.fair)/max*120:0;return `<g><title>${esc(tr(row.en,row.id))} ${row.shock}: ${rp(row.low)} / ${rp(row.high)}</title><text x="205" y="${y+10}" text-anchor="end">${esc(tr(row.en,row.id))}</text><text class="shock-label" x="205" y="${y+23}" text-anchor="end">${esc(row.shock)}</text><rect x="${335+Math.min(0,lo)}" y="${y}" width="${Math.max(.6,Math.abs(lo))}" height="8" fill="var(--blue)"/><rect x="${335+Math.min(0,hi)}" y="${y+10}" width="${Math.max(.6,Math.abs(hi))}" height="8" fill="var(--orange)"/><text x="${Math.min(485,340+Math.max(lo,hi))}" y="${y+13}">${fmt(row.impact)}</text></g>`;}).join('')}<text x="215" y="${height-8}">−${fmt(max)}</text><text x="335" y="${height-8}">0</text><text x="455" y="${height-8}" text-anchor="end">+${fmt(max)} Rp</text></svg><div class="caption">${tr('Change from base fair value; one driver at a time. Blue: lower assumption; orange: higher assumption. Exact shock sizes shown beside each driver.','Perubahan dari nilai dasar; satu pendorong diubah. Biru: asumsi lebih rendah; jingga: lebih tinggi. Besar perubahan ditampilkan pada tiap pendorong.')}</div><details class="tornado-detail"><summary>${tr('Driver values & shock definitions','Nilai pendorong & definisi perubahan')}</summary>${table([tr('Driver','Pendorong'),tr('Shock','Perubahan'),tr('Lower input','Input lebih rendah'),tr('Higher input','Input lebih tinggi')],rows.map(row=>[esc(tr(row.en,row.id)),esc(row.shock),rp(row.low),rp(row.high)]))}</details>`;}
function mcChart(){if(!mc)return empty(tr('Monte Carlo is available only for a supported fundamental valuation.','Monte Carlo tersedia hanya untuk valuasi fundamental yang didukung.'));const W=430,H=140,L=37,R=12,T=12,B=23,peak=Math.max(...mc.histogram.map(x=>x.count)),max=mc.histogram.at(-1).high,w=(W-L-R)/mc.histogram.length;return `<svg id="mc-svg" class="chart mc-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Monte Carlo fair-value distribution">${[0,.5,1].map(p=>`<line class="gridline" x1="${L}" x2="${W-R}" y1="${H-B-p*(H-T-B)}" y2="${H-B-p*(H-T-B)}"/><text x="${L-5}" y="${H-B-p*(H-T-B)+4}" text-anchor="end">${fmt(peak*p/mc.accepted*100,1)}%</text>`).join('')}${mc.histogram.map((b,i)=>`<rect x="${L+i*w}" y="${H-B-b.count/peak*(H-T-B)}" width="${Math.max(1,w-1)}" height="${b.count/peak*(H-T-B)}" fill="${b.high<c.price?'var(--red)':'var(--blue)'}" opacity=".8"/>`).join('')}${c.price<max?`<line x1="${L+c.price/max*(W-L-R)}" x2="${L+c.price/max*(W-L-R)}" y1="${T}" y2="${H-B}" stroke="var(--orange)" stroke-dasharray="3 2"/>`:''}${[0,.5,1].map(p=>`<text x="${L+p*(W-L-R)}" y="${H-5}" text-anchor="${p===0?'start':p===1?'end':'middle'}">${fmt(max*p)}</text>`).join('')}</svg><div class="mc-summary"><span>P10<b class="negative">${rp(mc.p10)}</b></span><span>P50<b>${rp(mc.p50)}</b></span><span>P90<b class="positive">${rp(mc.p90)}</b></span></div><div class="caption">${fmt(mc.accepted)} / ${fmt(mc.count)} ${tr('accepted draws','simulasi diterima')} · ${tr('seed','benih')} ${mc.seed} · ${pct(mc.aboveMarket)} ${tr('of model values above price','nilai model di atas harga')}. ${c.recoveryPlan?fmt(mc.fundingRejected||0)+' '+tr('recovery/funding draws rejected. ','simulasi pemulihan/pendanaan ditolak. '):''}${tr('Conditional valuation uncertainty, not investment odds.','Ketidakpastian nilai bersyarat, bukan peluang investasi.')}</div>`;}
function noteContent(){if(noteTab==='rating')return `<p><b>${esc(r.recommendation)} · ${esc(r.decision?.kind)} · ${esc(r.decision?.confidence)}</b></p><p>${decisionCriteria()}</p><p>${esc(r.rationale)}</p>`;if(noteTab==='risks')return `<ul><li>${r.dcf&&r.eligible?tr('Terminal value contributes ','Nilai terminal menyumbang ')+pct(r.dcf.terminalShare)+tr(' of intrinsic enterprise/equity value.',' dari nilai intrinsik perusahaan/ekuitas.'):tr('Insufficient fundamental evidence limits valuation confidence.','Bukti fundamental belum memadai.')}</li><li>${tr('Peer business mix, liquidity and one-off earnings may differ.','Bauran bisnis, likuiditas dan laba nonberulang pembanding dapat berbeda.')}</li><li>${tr('Annual shares proxy dilution; verify corporate actions and capital claims.','Saham tahunan menjadi proksi dilusi; verifikasi aksi korporasi dan klaim modal.')}</li><li>${tr('Forecast growth and discount rates are analyst assumptions.','Pertumbuhan dan diskonto adalah asumsi analis.')}</li></ul>`;if(noteTab==='sources')return `<p>${esc(c.source)}</p><p>${tr('Retrieved','Diambil')}: ${esc(c.updatedAt)}<br>${tr('Statements','Laporan')}: ${esc(c.period||'—')} · ${tr('Quote','Harga')}: ${esc(c.priceDate||'—')}</p><a href="${esc(universe.source)}" target="_blank" rel="noreferrer">${tr('Official IDX issuer directory','Direktori emiten resmi BEI')}</a>`;return `<ul><li>${esc(c.name)} · ${esc(c.industry||c.sector)}.</li><li>${tr('Price','Harga')} ${rp(c.price)} ${r.valid?tr('versus central value ','dibanding nilai pusat ')+rp(r.fair)+` (${pct(r.upside)}).`:tr('has no supported fundamental fair-value estimate.','belum memiliki estimasi nilai wajar fundamental yang didukung.')}</li><li>${r.valid?tr('Eligible intrinsic weight: ','Bobot intrinsik layak: ')+pct(r.weight,0)+tr('; relative weight: ','; bobot relatif: ')+pct(1-r.weight,0)+'.':esc(r.rationale)}</li><li>${tr('Selected-basis parent profit','Laba induk pada basis terpilih')}: ${fmt(c.netIncome)} ${tr('IDR bn','miliar IDR')}. ${tr('No invented catalysts or news are included.','Tanpa katalis atau berita rekaan.')}</li></ul>`;}
function notesPanel(){return `<div class="tabs-mini">${[['thesis',tr('Key Thesis','Tesis')],['risks',tr('Risks','Risiko')],['rating',tr('Why This Rating','Alasan Rating')],['sources',tr('Sources','Sumber')]].map(([id,l])=>`<button data-note="${id}" class="${noteTab===id?'active':''}">${l}</button>`).join('')}</div><div class="notes">${noteContent()}</div>`;}
function scenarioDescription(){return r.engine==='residual'?'Starting ROE -20%/+20%, Ke +1pp/-1pp; relative multiples -20%/+20% when eligible. Fixed method weights; five-year clean-surplus fade and zero terminal residual income.':r.engine==='core'?'Growth -3pp/+3pp, corporate margin -2.5pp/+2.5pp, risk-free rate +1pp/-1pp; relative multiples -20%/+20%, EV-to-equity bridge recomputed.':r.engine==='relative'?'Peer multiples -20%/+20%; EV-to-equity bridge recalculated.':'No fundamental scenario value is available for a technical/data-only decision.';}
function simulationControls(){return '<button data-view="lab" data-open-lab="scenarios">'+tr('Edit distributions and correlations','Ubah distribusi dan korelasi')+' ↗</button><div class="controls"><label>'+tr('Draws','Simulasi')+' <select id="mc-count">'+[500,2000,5000,10000].map(n=>'<option '+(n===mcCount?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label>'+tr('Seed','Benih')+' <input id="mc-seed" type="number" min="0" max="4294967295" value="'+mcSeed+'"></label><button data-action="simulate">'+tr('Run simulation','Jalankan simulasi')+'</button></div><p class="caption">'+tr('Selected shocks','Stres terpilih')+': '+(r.engine==='relative'?'peer-multiple sigma '+pct(mcConfig.multipleSigma):r.engine==='residual'?'cost-of-equity sigma '+pct(mcConfig.rateSigma)+'; starting-ROE / peer-multiple sigma '+pct(mcConfig.multipleSigma):'growth sigma '+pct(mcConfig.growthSigma)+'; margin sigma '+pct(mcConfig.marginSigma)+'; risk-free sigma '+pct(mcConfig.rateSigma)+'; terminal sigma '+pct(mcConfig.terminalSigma)+'; multiple sigma '+pct(mcConfig.multipleSigma)+'; correlation '+fmt(mcConfig.correlation,2))+'. '+tr('Analyst-selected conditional model uncertainty; not investment odds.','Ketidakpastian model bersyarat pilihan analis; bukan peluang investasi.')+'</p>';}

function assumptionsForm(scope='all'){if(scope==='forecast'&&c.recoveryPlan)return '<p class="input-scope-note">'+tr('The six year-specific operating paths above control this recovery forecast. Review and apply changes in that table. Shared forecast defaults do not override these paths.','Enam jalur operasi per tahun di atas mengendalikan proyeksi pemulihan ini. Tinjau dan terapkan perubahan pada tabel tersebut. Asumsi umum tidak menimpa jalur ini.')+'</p>';const active=pageAssumptions(c,r,scope),planning=scope==='forecast'&&!(r.engine==='residual'||r.engine==='core'&&r.eligible&&r.weight>0);const labelFor=k=>k==='growth'?planning?tr('Planning denominator growth','Pertumbuhan penyebut perencanaan'):financial(c)?tr('Earnings growth','Pertumbuhan laba'):tr('Revenue growth','Pertumbuhan pendapatan'):tr(...paramLabels[k]);if(!active.length)return empty(tr('No editable assumptions for this evidence basis.','Tidak ada asumsi yang dapat diubah untuk dasar bukti ini.'));return `<div class="input-scope-note"><span>${scope==='valuation'?tr('Discount, terminal value and decision rules','Diskonto, nilai terminal, dan aturan keputusan'):planning?tr('Planning display only; excluded from current fair value','Hanya tampilan perencanaan; di luar nilai wajar kini'):tr('Analyst estimates; linked model outputs update on edit','Estimasi analis; hasil model terkait berubah saat input diubah')}</span><button class="text-action" data-action="reset">${tr('Reset these inputs','Atur ulang input ini')}</button></div><div class="assumptions ${scope!=='all'?'focused-assumptions':''}">${active.map(k=>`<label>${esc(labelFor(k))}${k==='beta'?'':' (%)'}<input data-param="${k}" aria-label="${esc(labelFor(k))}" type="number" step="${k==='beta'?'.05':'.1'}" value="${Number((a[k]*(k==='beta'?1:100)).toFixed(3))}"></label>`).join('')}</div><div class="controls"><button data-action="recalculate">${scope==='forecast'?tr('Update forecast','Perbarui proyeksi'):tr('Recalculate valuation','Hitung ulang valuasi')}</button></div>`;}

function dashboard(){return `<div class="trading-workspace">${chartWorkspace()}${recommendationPanel()}</div><div class="grid research-grid">${panel(3,tr('VALUATION BREAKDOWN','RINCIAN VALUASI'),breakdown(),4)}${panel(10,tr('MONTE CARLO · FAIR VALUE','MONTE CARLO · NILAI WAJAR'),mcChart(),4,`<button class="text-action" data-view="sensitivity">${tr('Configure','Atur')} ↗</button>`)}${panel(5,tr('KEY METRICS','METRIK UTAMA'),metrics(),4,`<small>${esc(c.period||'—')}</small>`)}${panel(4,tr('KEY FINANCIALS','KEUANGAN UTAMA'),financialTable(),7,'<small>IDR bn</small>')}${panel(6,tr('RELATIVE VALUATION · PEERS','VALUASI RELATIF · PEMBANDING'),peerTable(),5)}${panel(8,tr('SENSITIVITY ANALYSIS','ANALISIS SENSITIVITAS'),heatmap(),4)}${panel(7,tr('WEIGHTED SCENARIO SUMMARY','RINGKASAN SKENARIO TERTIMBANG'),dcfSummary(),4)}${panel(9,tr('VALUE DRIVERS · TORNADO','PENDORONG NILAI · TORNADO'),driverChart(),4)}${panel(11,tr('RESEARCH THESIS & RECOMMENDATION','TESIS RISET & REKOMENDASI'),notesPanel(),12)}</div>`;}

function checksView(){return `<div class="stats-strip"><span>${tr('Errors','Galat')} <b class="negative">${r.checks.filter(x=>x.level==='error').length}</b></span><span>${tr('Warnings','Peringatan')} <b class="accent">${r.checks.filter(x=>x.level==='warning').length}</b></span><span>${tr('Rating basis','Dasar rating')} <b>${r.basis}</b></span></div><div class="panel">${r.checks.length?r.checks.map(x=>`<div class="check"><b class="${x.level==='error'?'negative':'accent'}">${esc(x.code)}</b><p>${esc(lang==='id'?x.id:x.en)}</p></div>`).join(''):empty(tr('No validation findings.','Tidak ada temuan validasi.'))}</div><div class="caption">${tr('Validation checks are method-specific. Missing cash-flow inputs may exclude DCF while an industry relative model remains possible. Technical signals are labeled separately and never imply fair value.','Validasi mengikuti metode. Input arus kas kosong dapat mengecualikan DCF sementara metode relatif masih layak. Sinyal teknikal diberi label terpisah dan tidak menyiratkan nilai wajar.')}</div>`;}
function screener(){const filtered=coverage.filter(x=>(!filter||`${x.ticker} ${x.name}`.toLowerCase().includes(filter.toLowerCase()))&&(!sector||x.idxSector===sector)&&(!rating||x.recommendation===rating)&&(!basis||x.basis===basis)&&(!screenKind||x.decisionKind===screenKind)&&(minUpside===''||x.upside>=Number(minUpside)/100)&&(minVolume===''||x.volume>=Number(minVolume))).sort((a,b)=>{const av=a[sortKey],bv=b[sortKey];return sortDirection*(typeof av==='number'&&typeof bv==='number'?av-bv:String(av??'').localeCompare(String(bv??'')));});page=Math.min(page,Math.max(0,Math.ceil(filtered.length/40)-1));const rows=filtered.slice(page*40,(page+1)*40);return `<div class="view-title">${tr('IDX Universe · Coverage Monitor','Semesta BEI · Monitor Cakupan')}</div><div class="stats-strip"><span>${tr('Listed issuers','Emiten tercatat')} <b>${universe.total}</b></span><span>${tr('Fundamental','Fundamental')} <b class="blue">${coverage.filter(x=>x.basis==='FUNDAMENTAL').length}</b></span><span>${tr('Conditional value','Nilai bersyarat')} <b class="accent">${coverage.filter(x=>x.basis==='INDICATIVE').length}</b></span><span>${tr('Technical only','Hanya teknikal')} <b class="accent">${coverage.filter(x=>x.basis==='TECHNICAL').length}</b></span><span>WAIT <b class="negative">${coverage.filter(x=>x.recommendation==='WAIT').length}</b></span><span>${tr('Intrinsic + relative','Intrinsik + relatif')} <b>${coverage.filter(x=>x.methodCoverage==='BOTH').length}</b></span><span>DCF + relative <b>${coverage.filter(x=>x.dcfComparison==='DCF_AND_RELATIVE').length}</b></span><span>${tr('Provider scanned','Data dipindai')} <b>${catalog.completed||0}/${universe.total}</b></span></div><div class="controls"><input id="screen-search" placeholder="${tr('Filter ticker / company','Saring kode / emiten')}" value="${esc(filter)}"><select id="screen-sector"><option value="">${tr('All sectors','Semua sektor')}</option>${[...new Set(universe.issuers.map(x=>x.idxSector))].sort().map(x=>`<option ${sector===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="screen-rating"><option value="">${tr('All outcomes','Semua hasil')}</option>${['BUY','HOLD','SELL','WAIT'].map(x=>`<option ${rating===x?'selected':''}>${x}</option>`).join('')}</select><select id="screen-basis"><option value="">${tr('All evidence','Semua dasar')}</option>${['FUNDAMENTAL','INDICATIVE','TECHNICAL','UNRATED'].map(x=>`<option ${basis===x?'selected':''}>${x}</option>`).join('')}</select><select id="screen-kind" aria-label="Decision type"><option value="">${tr('All decision types','Semua jenis keputusan')}</option>${['VALUATION','TECHNICAL','DATA'].map(v=>`<option ${screenKind===v?'selected':''}>${v}</option>`).join('')}</select><input id="screen-upside" type="number" value="${minUpside}" placeholder="${tr('Min upside %','Min potensi %')}" aria-label="Minimum upside percent"><input id="screen-volume" type="number" min="0" value="${minVolume}" placeholder="${tr('Min volume','Min volume')}" aria-label="Minimum traded volume"><select id="screen-sort" aria-label="Sort issuers">${[['ticker','Ticker'],['upside','Upside'],['price','Price'],['fair','Fair value'],['volume','Volume']].map(([v,l])=>`<option value="${v}" ${sortKey===v?'selected':''}>${l}</option>`).join('')}</select><button data-action="sort-direction">${sortDirection===1?'↑':'↓'}</button><span class="grow"></span><button data-action="directory-refresh">${tr('Refresh IDX directory','Perbarui direktori BEI')}</button><button data-action="coverage">↓ ${tr('Coverage CSV','CSV cakupan')}</button></div><div class="panel screener">${table([tr('Ticker','Kode'),tr('Company','Emiten'),tr('Industry','Industri'),tr('Price Rp','Harga Rp'),tr('Fair Rp','Wajar Rp'),tr('Upside','Potensi'),tr('Outcome','Hasil'),tr('Basis / assurance','Dasar / kepastian'),tr('Method coverage','Cakupan metode'),tr('Quote','Harga'),tr('FY','TA')],rows.map(x=>[`<button class="ticker-link" data-ticker="${x.ticker}">${x.ticker} ↗</button>`,esc(x.name),esc(x.industry),fmt(x.price),fmt(x.fair),`<span class="${color(x.upside)}">${pct(x.upside)}</span>`,`<span class="${x.recommendation==='BUY'?'positive':x.recommendation==='SELL'?'negative':'accent'}">${x.recommendation}</span>`,`<span class="badge ${x.basis==='FUNDAMENTAL'?'blue':'muted'}">${x.basis}</span><small class="peer-business" title="${esc(x.reason)}">${esc(x.confidence||'—')} · ${esc(x.method||'—')} ${x.dependencyStatus?' · '+esc(x.dependencyStatus):''}</small>`,`<span class="badge">${esc(x.methodCoverage||'INCOMPLETE')}</span><small class="peer-business">${esc(x.dcfComparison||'INCOMPLETE')}</small>`,esc(x.priceDate||'—'),esc(x.period||'—')]))}<div class="pagination"><span>${filtered.length} ${tr('issuers','emiten')} · ${filtered.length?page*40+1:0}–${Math.min((page+1)*40,filtered.length)}</span><div><button data-page="-1" ${page===0?'disabled':''}>←</button> <button data-page="1" ${(page+1)*40>=filtered.length?'disabled':''}>→</button></div></div></div><div class="caption">${tr('Every official issuer has a coverage outcome. BUY/HOLD/SELL are explicitly labelled as valuation estimates or technical signals. WAIT means a blocking issue remains; it is not HOLD. Snapshot quotes and accounts retain their original dates. Open an issuer to refresh its feed.','Setiap emiten resmi memiliki hasil cakupan. BUY/HOLD/SELL diberi label estimasi valuasi atau sinyal teknikal. WAIT berarti ada kendala penting; bukan HOLD. Tanggal harga dan laporan asli dipertahankan. Buka emiten untuk memperbarui data.')}<br>${tr('Directory','Direktori')}: <a href="${esc(universe.source)}" target="_blank" rel="noreferrer">IDX</a> · ${universe.asOf} · ${tr('Audit updated','Audit diperbarui')}: ${esc(catalog.updatedAt||'—')}.</div>`;}
function exportView(){return `<div class="view-title">${tr('Research exports','Ekspor riset')} · ${c.ticker}</div><div class="export-grid">${[['excel','Excel · .xlsx',tr('Editable inputs and assumptions, linked calculations and formulas. Includes simulation statistics and audit trail.','Input dan asumsi dapat diedit, kalkulasi serta formula terhubung. Termasuk statistik simulasi dan jejak audit.')],['pdf','Research report · .pdf',tr('Methods, forecasts, peers, sensitivity, assumptions, validation findings and Monte Carlo exhibits.','Metode, proyeksi, pembanding, sensitivitas, asumsi, validasi dan eksibit Monte Carlo.')],['template',tr('Input template · .xlsx','Templat input · .xlsx'),tr('Structured annual inputs, historical data, assumptions and peers. Upload to recalculate.','Input tahunan, data historis, asumsi dan pembanding terstruktur. Unggah untuk menghitung ulang.')],['save','Workspace · .json',tr('Save the exact financial inputs, source metadata and current assumptions for reproducibility.','Simpan input, metadata sumber dan asumsi kini agar dapat direproduksi.')],['coverage','IDX Coverage · .csv',tr('All listed issuers, recommendation basis, source dates and unavailable-data reasons.','Seluruh emiten, dasar rekomendasi, tanggal sumber dan alasan data tidak tersedia.')],['upload',tr('Import data','Impor data'),tr('Load the RALVEN Excel template or a saved JSON workspace. Files stay in your browser.','Muat templat Excel RALVEN atau workspace JSON tersimpan. File diproses di peramban.')]].map(([action,title,desc])=>`<div class="export-card"><h3>${title}</h3><p>${desc}</p><button data-action="${action}">${action==='upload'?tr('Choose file','Pilih file'):tr('Download','Unduh')} ↗</button></div>`).join('')}</div>`;}
function dataView(){return `<div class="grid">${panel(1,tr('COMPANY & SOURCE REGISTER','EMITEN & DAFTAR SUMBER'),table([tr('Field','Kolom'),tr('Value','Nilai')],[['Ticker',c.ticker],[tr('Company','Emiten'),esc(c.name)],[tr('IDX sector','Sektor BEI'),esc(c.idxSector||c.sector)],[tr('Industry','Industri'),esc(c.industry||'—')],[tr('Board','Papan'),esc(c.board||'—')],[tr('Quote date','Tanggal harga'),esc(c.priceDate||'—')],[tr('Fiscal period','Periode laporan'),esc(c.period||'—')],[tr('Retrieved','Diambil'),esc(c.updatedAt)],[tr('Units','Satuan'),esc(c.units)],[tr('Mode','Mode'),c.mode]])+`<div class="caption">${esc(c.source)}</div>`,6)}${panel(2,tr('HISTORICAL STATEMENTS','LAPORAN HISTORIS'),historicalStatements(c,{tr,fmt,table,esc}),12)}${panel(3,tr('FISCAL-DATE FX REGISTER','DAFTAR KURS TANGGAL LAPORAN'),table(['Currency','Date','IDR / unit','Source'],(c.fx||[]).map(f=>[f.currency,f.date,fmt(f.rate,4),esc(f.source)]))+`<div class="caption">${tr('Fiscal-date closing FX translates reporting currency to IDR; shares are not converted. This simplified translation is not an audited restatement.','Kurs penutupan tanggal laporan mengonversi mata uang ke IDR; saham tidak dikonversi. Translasi sederhana ini bukan penyajian ulang yang diaudit.')}</div>`,6)}${panel(4,tr('PROVIDER NOTES','CATATAN PENYEDIA'),`<div class="notes"><ul>${[...(c.dataNotes||[]),...(c.providerErrors||[])].map(n=>`<li>${esc(n)}</li>`).join('')||'<li>—</li>'}</ul></div>`,6)}</div>`;}
function researchHelpers(){return {tr,fmt,pct,rp,esc,table,panel,assumptionsForm,decisionCriteria};}
function content(){if(view==='lab')return researchWorkbench(c,a,r,stateForCompany(),researchHelpers());if(view==='screener')return screener();if(view==='export')return exportView();if(view==='integrity')return `<div class="grid">${panel(1,tr('RECOMMENDATION GATES','SYARAT REKOMENDASI'),checksView(),12)}${panel(2,tr('SOURCE RECONCILIATION','REKONSILIASI SUMBER'),evidenceMarkup(c,r,{tr,fmt,esc,table}),12)}</div>`;if(view==='data')return remediationWorkbench(c,r,researchHelpers())+recoveryMarkup(c,a,r,{tr,esc,fmt,table})+`<div class="grid">${panel(1,tr('SOURCE STATEMENT EXPLORER','PENJELAJAH LAPORAN SUMBER'),statementExplorer(c,{tr,fmt,esc,table}),12)}${panel(2,tr('MODEL INPUTS & RECONCILIATION','INPUT MODEL & REKONSILIASI'),evidenceMarkup(c,r,{tr,fmt,esc,table}),12)}${panel(3,tr('COMPANY & HISTORY','EMITEN & HISTORIS'),dataView(),12)}</div>`;if(view==='financials')return `<div class="grid">${panel(1,tr('HISTORICAL & FORECAST FINANCIALS','KEUANGAN HISTORIS & PROYEKSI'),financialTable(),8)}${panel(2,tr('METRICS','METRIK'),metrics(),4)}${panel(3,tr('SOURCE REGISTER','DAFTAR SUMBER'),dataView(),12)}</div>`;if(view==='peers')return peerEditor(c,r,researchHelpers())+`<div class="grid peer-page">${panel(1,tr('INDUSTRY COMPARABLES','PEMBANDING INDUSTRI'),peerTable(true),8)}${panel(2,tr('RELATIVE VALUATION · EQUITY BRIDGE','VALUASI RELATIF · REKONSILIASI EKUITAS'),relativeBridge(),4)}</div>`;if(view==='valuation')return valuationPage(c,a,r,researchHelpers());if(view==='forecast')return recoveryMarkup(c,a,r,{tr,esc,fmt,table})+(a.paths?.some(path=>Object.keys(path).length)?'<div class="forecast-link-note"><b>'+tr('Year-specific operating overrides are active.','Penyesuaian operasi per tahun aktif.')+'</b> <button data-view="lab" data-open-lab="scenarios">'+tr('Review driver paths','Tinjau jalur penggerak')+' ↗</button></div>':'')+forecastPage(c,a,r,researchHelpers(),{metric:forecastMetric});if(view==='sensitivity')return `<div class="grid">${panel(1,tr('MONTE CARLO · VALUATION DISTRIBUTION','MONTE CARLO · DISTRIBUSI VALUASI'),simulationControls()+mcChart()+`<div class="caption">${esc(mc?.description||'')} ${tr('P10/P90 are simulation percentiles; bear/bull are separate deterministic scenarios.','P10/P90 adalah persentil simulasi; pesimis/optimis adalah skenario deterministik terpisah.')}</div>`,6)}${panel(2,tr('SENSITIVITY MATRIX','MATRIKS SENSITIVITAS'),heatmap(),6)}${panel(3,tr('VALUE DRIVERS','PENDORONG NILAI'),driverChart(),6)}${panel(4,tr('SCENARIO COMPARISON','PERBANDINGAN SKENARIO'),dcfSummary(),6)}${panel(5,tr('ASSUMPTIONS','ASUMSI'),assumptionsForm(),12)}</div>`;if(view==='metrics')return `<div class="grid">${panel(1,tr('OPERATING & EQUITY METRICS','METRIK OPERASI & EKUITAS'),metrics(),6)}${panel(2,tr('PRICE SIGNALS','SINYAL HARGA'),table(['Metric','Value'],[['Observations',fmt(c.technicals?.observations)],['SMA 20',rp(c.technicals?.sma20)],['SMA 50',rp(c.technicals?.sma50)],['SMA 200',rp(c.technicals?.sma200)],['RSI 14',fmt(c.technicals?.rsi,1)],['63-session momentum',pct(c.technicals?.momentum)]])+`<div class="caption">${tr('Technical signals are separate from intrinsic valuation. RSI uses simple 14-change gains/losses.','Sinyal teknikal terpisah dari valuasi intrinsik. RSI memakai rata-rata sederhana untung/rugi 14 perubahan.')}</div>`,6)}</div>`;if(view==='notes')return `<div class="grid">${panel(1,tr('RESEARCH NOTES','CATATAN RISET'),notesPanel(),6)}${panel(2,tr('VALIDATION','VALIDASI'),checksView(),6)}</div>`;return dashboard();}
function render(){document.documentElement.dataset.theme=theme;document.documentElement.dataset.density=researchState.density;document.documentElement.lang=lang;if(!c){$('#app').innerHTML=`<div class="app-loading"><div class="loading-mark"><img src="/logo.png" alt="RALVEN logo"></div><b>RALVEN</b><span>${tr('Preparing your research workspace…','Menyiapkan ruang riset Anda…')}</span></div>`;return;}const change=c.previousClose>0?c.price/c.previousClose-1:null,market=c.price*c.shares,valid=r.quality?.actionable;$('#app').innerHTML=`<header class="top"><a class="brand" href="/" aria-label="RALVEN"><img class="crest" src="/logo.png" alt=""><div><strong>RALVEN</strong><small>${tr('EQUITY RESEARCH','RISET EKUITAS')}</small></div></a><nav class="topnav" aria-label="${tr('Main navigation','Navigasi utama')}">${[['overview',tr('Workspace','Ruang kerja')],['screener',label('screener')],['sensitivity',tr('Scenarios','Skenario')],['export',tr('Export','Ekspor')]].map(([v,l])=>`<button data-view="${v}" class="${view===v?'active':''}">${l}</button>`).join('')}</nav><div class="header-tools"><span class="market-universe">IDX <b>${universe.total}</b></span><button class="language-button" data-action="language" aria-label="${tr('Switch to Indonesian','Ganti ke Inggris')}">${lang.toUpperCase()}</button><button class="icon-button" data-action="theme" aria-label="${tr('Toggle light or dark theme','Ganti tema terang atau gelap')}">${uiIcon(theme==='dark'?'moon':'sun')}</button><button class="header-export" data-action="excel" aria-label="${tr('Export Excel model','Ekspor model Excel')}">${uiIcon('export')}<span>${tr('Export model','Ekspor model')}</span></button></div></header><div class="shell"><aside><nav class="side" aria-label="${tr('Research tools','Alat riset')}">${[['overview','workspace',tr('Workspace','Ruang kerja')],['screener','market',tr('Markets','Pasar')],['data','data',tr('Data','Data')],['valuation','model',tr('Valuation','Valuasi')],['forecast','chart',tr('Forecast','Proyeksi')],['peers','peers',tr('Peers','Pembanding')],['integrity','shield',tr('Integrity','Integritas')],['lab','chart',tr('Research lab','Pusat riset')],['export','export',tr('Export','Ekspor')]].map(([v,i,l])=>`<button data-view="${v}" class="${view===v?'active':''}" title="${l}">${uiIcon(i)}<span>${l}</span></button>`).join('')}</nav><div class="rail-bottom"><button data-action="upload" title="${tr('Import workbook','Impor workbook')}">${uiIcon('plus')}<span>${tr('Import','Impor')}</span></button><span class="rail-avatar" aria-label="${tr('Academic workspace','Ruang akademik')}">R</span></div></aside><main class="main ${busy?'loading':''}" aria-busy="${busy}"><div class="workspace-top"><form class="search" id="ticker-form">${uiIcon('search')}<input id="ticker-search" list="tickers" autocomplete="off" placeholder="${tr('Find an IDX company','Cari emiten BEI')}" aria-label="${tr('IDX ticker','Kode saham BEI')}"><button aria-label="${tr('Analyze ticker','Analisis kode')}">${uiIcon('arrow')}</button><kbd>Ctrl K</kbd><datalist id="tickers">${universe.issuers.map(p=>`<option value="${p.ticker}">${esc(p.name)}</option>`).join('')}</datalist></form><span class="workspace-date">${tr('Valuation date','Tanggal valuasi')} <b>${esc(c.valuationDate)}</b></span></div>${assetStrip()}<div class="quote"><div class="ticker">${esc(c.ticker)}</div><div class="company-description"><div class="company">${esc(c.name)}</div><div class="meta">IDX <span>·</span> ${esc(c.industry||c.sector)} <span>·</span> IDR</div></div><div class="quote-stat"><small>${tr('Market cap','Kapitalisasi pasar')}</small><b>${market>0?'Rp '+fmt(market/1000,1)+' T':'—'}</b></div><div class="quote-stat"><small>${tr('Shares outstanding','Saham beredar')}</small><b>${fmt(c.shares,2)} B</b></div><div class="quote-stat range-stat"><small>${tr('52-week high / low','Tertinggi / terendah 52M')}</small><b>${fmt(c.high52)} / ${fmt(c.low52)}</b></div><button data-view="integrity" class="status ${!valid?'warning':''}"><span class="status-dot"></span>${c.mode==='demo'?'SYNTHETIC':esc(r.quality?.status||'UNVERIFIED')}</button></div><nav class="subnav" aria-label="${tr('Company analysis','Analisis emiten')}">${['overview','financials','valuation','forecast','peers','sensitivity','metrics','notes','lab'].map(v=>`<button data-view="${v}" class="${view===v?'active':''}">${label(v)}</button>`).join('')}<button class="mobile-only" data-view="data">${tr('Data','Data')}</button><button class="mobile-only" data-view="screener">IDX ${universe.total}</button><button class="mobile-only" data-view="export">${tr('Export / Import','Ekspor / Impor')}</button></nav><div class="workspace-banner"><span><span class="source-indicator"></span>${c.mode==='demo'?tr('Synthetic sample','Contoh sintetis'):c.mode==='import'?tr('Imported data','Data impor'):tr('Market data','Data pasar')} <span class="banner-divider">/</span> ${esc(c.periodBasis||'ANNUAL')} ${esc(c.period||'—')} <span class="banner-divider">/</span> ${esc(r.basis)} <span class="banner-divider">/</span> <button data-view="valuation" class="text-action">${esc(r.methodAssessment?.coverage||'INCOMPLETE')} · ${r.methodAssessment?.courseComparison==='DCF_AND_RELATIVE'?'DCF + relative':tr('DCF incomplete','DCF belum lengkap')}</button>${c.archivedCase?' / '+tr('Archived case','Kasus arsip'):''}</span><button data-action="refresh">${uiIcon('refresh')}${busy?tr('Updating…','Memperbarui…'):tr('Refresh data','Perbarui data')}</button></div>${c.mode==='demo'?'<div class="evidence-banner review"><b>'+tr('SYNTHETIC CLASSROOM EXAMPLE · All subject and peer inputs are fictional. Not an issuer valuation or investment recommendation.','CONTOH KELAS SINTETIS · Seluruh input subjek dan pembanding fiktif. Bukan valuasi emiten atau rekomendasi investasi.')+'</b></div>':''}${error?`<div class="error-message">${esc(error)}</div>`:''}${view==='overview'?'':evidenceBanner()}${['valuation','integrity'].includes(view)?methodMarkup(c,r,{tr,esc,table,rp,pct}):''}${content()}</main></div><footer class="footer"><span><i class="footer-dot"></i>IDX ${tr('research','riset')}</span><span>${tr('Quote','Harga')} ${esc(c.priceDate||'—')}</span><span>${tr('Assessed','Diproses')} ${coverage.length}/${universe.total}</span><span class="right footer-contact"><span>Yusuf Zakaria</span><a href="mailto:yusufzaakaria@gmail.com">yusufzaakaria@gmail.com</a><a href="https://www.linkedin.com/in/yusuf-zakaria" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a></span></footer>`;bind();}

function saveBlob(data,type,name){const url=URL.createObjectURL(new Blob([data],{type})),el=document.createElement('a');el.href=url;el.download=name;el.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function coverageCSV(){const keys=['ticker','name','idxSector','industry','recommendation','basis','method','methodCoverage','dcfComparison','intrinsicModel','intrinsicStatus','relativeStatus','methodBlockers','price','fair','upside','priceDate','period','updatedAt','sourceStatus','verifiedInputs','requiredInputs','periodBasis','decisionKind','decisionStatus','confidence','requirements','snapshotId','dependencyStatus','reason'];saveBlob('\ufeff'+[keys,...coverage.map(x=>keys.map(k=>x[k]??''))].map(row=>row.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv',`RALVEN_IDX_Coverage_${universe.asOf}.csv`);}
function workbookSnapshot(){return {company:c,assumptions:{...a},result:r,simulation:mc};}
async function exportWorkbook(){const exportState=workbookSnapshot();const subject=exportState.company,params=exportState.assumptions,result=exportState.result,simulation=exportState.simulation;const sourceFacts=await statementWorkbook(subject.ticker);const spec=researchSpec(subject,params,result);spec['Source Statement Facts']=sourceFacts;spec['Source Filing Notes']=await statementNotesWorkbook(subject.ticker);spec['Capital Schedule Checks']=await statementCapitalWorkbook(subject.ticker);const c=subject,r=result,mc=simulation;spec['Coverage Notes']=[['RALVEN '+release.engine],['Industry',c.industry||c.sector],['Rating basis',r.basis],['Original quote date',c.priceDate],['Fiscal period',c.period],['Retrieval timestamp',c.updatedAt],['Source',c.source],['FX rule','Fiscal-date closing rate; shares never FX-converted.'],['Simulation','Snapshot only. Monte Carlo draws are computed by the documented JS engine; not recalculated in Excel.'],['Peer membership','Frozen at export; refresh source data to rescreen.']];spec['Monte Carlo']=mc?[['Conditional fair-value simulation'],['Seed',mc.seed],['Attempted draws',mc.count],['Accepted',mc.accepted],['Rejected',mc.rejected],['Recovery / funding rejections',mc.fundingRejected||0],['P10',mc.p10],['P50',mc.p50],['P90',mc.p90],['Fraction above market',mc.aboveMarket],['Method',mc.description],['Bin low','Bin high','Count'],...mc.histogram.map(x=>[x.low,x.high,x.count])]:[['Monte Carlo unavailable'],['Reason',r.rationale]];downloadExcel(spec,`RALVEN_${c.ticker}_${c.valuationDate}.xlsx`);}
async function report(){const notes=await loadStatements(c.ticker),filingNoteIndex=(notes.reports||[]).map(x=>({period:x.periods?.[0],count:x.notes?.length||0,url:x.url,omitted:x.noteCoverage?.omitted||0}));return researchReport({filingNoteIndex,company:c,assumptions:a,result:r,simulation:mc,lang,analystNotes:issuerState().notes,scenario:issuerState().activeScenario||'Base',simulationConfig:mcConfig});}

const actions={search:()=>$('#ticker-search').focus(),refresh:()=>load(c.ticker),language:()=>{lang=lang==='en'?'id':'en';localStorage.setItem('ralven-lang',lang);render();},theme:()=>{theme=theme==='dark'?'light':'dark';localStorage.setItem('ralven-theme',theme);render();},upload:()=>$('#file').click(),template:()=>{const s=sample('TLKM');const spec=templateSpec(s,assumptions(s));Object.assign(spec,evidenceSheets(s,analyzeCompany(s,assumptions(s))));spec.Instructions.push(['Evidence','Optional Evidence, FX and Profile sheets preserve field-level source references. Imported references are user supplied and require review; they are not certified primary facts.']);downloadExcel(spec,'RALVEN_Input_Template.xlsx');},excel:exportWorkbook,pdf:report,coverage:coverageCSV,save:()=>saveBlob(JSON.stringify({schema:release.schema,engineVersion:release.engine,snapshotId:snapshotId(c,a),company:c,assumptions:a,simulation:{...mcConfig,count:mcCount,seed:mcSeed},research:stateForCompany()},null,2),'application/json',`RALVEN_${c.ticker}_Workspace.json`),reset:()=>{const estimates=assumptions(c);const keys=pageAssumptions(c,r,['forecast','valuation'].includes(view)?view:'all');for(const key of keys.length?keys:Object.keys(estimates))a[key]=estimates[key];if(a.paths)a.paths=a.paths.map(path=>Object.fromEntries(Object.entries(path).filter(([key])=>!keys.includes(key))));recalc();render();},recalculate:()=>{syncAssumptions();recalc();render();notify(tr('All methods recalculated.','Seluruh metode dihitung ulang.'));},simulate:()=>{mcCount=Number($('#mc-count').value);mcSeed=Number($('#mc-seed').value)>>>0;recalc();render();}};
function syncAssumptions(){for(const el of document.querySelectorAll('[data-param]')){a[el.dataset.param]=el.value===''?NaN:Number(el.value)/(el.dataset.param==='beta'?1:100);}}
function bind(){bindResearch();document.querySelectorAll('[data-forecast-metric]').forEach(el=>el.onclick=()=>{forecastMetric=el.dataset.forecastMetric;render();});bindStatementExplorer(c,{tr,fmt,esc,table},render);$('#ticker-form').onsubmit=e=>{e.preventDefault();load($('#ticker-search').value);};document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>{if(el.dataset.openLab)researchState.tab=el.dataset.openLab;view=el.dataset.view;render();});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=async()=>{try{await actions[el.dataset.action]?.();}catch(e){notify(e.message);}});document.querySelectorAll('[data-ticker]').forEach(el=>el.onclick=()=>load(el.dataset.ticker));document.querySelectorAll('[data-note]').forEach(el=>el.onclick=()=>{noteTab=el.dataset.note;render();});document.querySelectorAll('[data-chart-mode]').forEach(el=>el.onclick=()=>{chartMode=el.dataset.chartMode;render();});document.querySelectorAll('[data-range]').forEach(el=>el.onclick=()=>{chartRange=el.dataset.range;render();});document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{page+=Number(el.dataset.page);render();});document.querySelectorAll('[data-param]').forEach(el=>{el.oninput=()=>{if(el.value!==''&&Number.isFinite(Number(el.value)))a[el.dataset.param]=Number(el.value)/(el.dataset.param==='beta'?1:100);c.assumptionMeta??={};c.assumptionMeta[el.dataset.param]={basis:'ANALYST',source:'Edited in RALVEN',sourceDate:c.valuationDate,rationale:'Analyst override; add issuer-specific rationale in Research lab.'};};el.onchange=()=>{syncAssumptions();recalc();render();};});for(const [id,set] of [['screen-search',v=>filter=v],['screen-sector',v=>sector=v],['screen-rating',v=>rating=v],['screen-basis',v=>basis=v],['screen-kind',v=>screenKind=v],['screen-upside',v=>minUpside=v],['screen-volume',v=>minVolume=v],['screen-sort',v=>sortKey=v]]){const el=$('#'+id);if(el)el.onchange=()=>{set(el.value);page=0;render();};}}
function manualWorkspace(raw){if(raw.mode==='demo')return raw;const downgrade=p=>{const next={...p,mode:'import',observations:(p.observations||[]).map(o=>({...o,sourceId:'manual-workspace',sourceGroup:'manual',sourceType:'manual'})),source:'User-imported workspace; source assertions not independently verified. '+(p.source||'')};next.providerSnapshot=Object.fromEntries((p.evidence?.rows||[]).map(row=>[row.field,row.selected]));next.providerPeriod=p.period;delete next.evidence;return next;};return {...downgrade(raw),peerUniverse:(raw.peerUniverse||raw.peers||[]).map(downgrade),peers:(raw.peers||[]).map(downgrade)};}
$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{let data;if(file.name.endsWith('.json')){if(file.size>5e6)throw Error('Maximum 5 MB.');const raw=JSON.parse(await file.text());if(!['RALVEN-2',release.schema].includes(raw.schema)||!raw.company||!raw.assumptions)throw Error('Invalid RALVEN workspace.');mcConfig=normalizeSimulation(raw.simulation||{});mcCount=mcConfig.count;mcSeed=mcConfig.seed;if(raw.research){researchState.byIssuer[raw.company.ticker]={...raw.research,remoteHistory:[]};}data={c:manualWorkspace(raw.company),a:{...defaults,...raw.assumptions}};if(!['demo','live','import'].includes(data.c.mode))throw Error('Invalid source mode.');if(!Array.isArray(data.c.history)||!Array.isArray(data.c.peers))throw Error('Invalid history / peers.');}else data=await parseImport(file);setCompany(data.c,data.a,{historical:file.name.endsWith('.json')});view='overview';error='';render();notify(tr('Imported and recalculated.','Diimpor dan dihitung ulang.'));}catch(err){notify(err.message);}finally{e.target.value='';}};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#ticker-search')?.focus();}});

function evidenceBanner(){if(c.mode==='demo')return '';const blocked=r.recommendation==='WAIT',conditional=r.basis==='INDICATIVE',technical=r.engine==='technical';return `<div class="evidence-banner ${blocked||conditional||technical?'review':'ready'}"><div><b>${blocked?tr('WAIT · ACTION REQUIRED','TUNGGU · PERLU TINDAKAN'):technical?tr('TECHNICAL SIGNAL · LOW ASSURANCE','SINYAL TEKNIKAL · KEPASTIAN RENDAH'):conditional?tr('CONDITIONAL VALUATION','VALUASI BERSYARAT'):tr('VALUATION · SOURCE CHECKS PASSED','VALUASI · PEMERIKSAAN SUMBER LOLOS')}</b> · ${blocked?tr('Resolve the requirements before using a trading rating.','Selesaikan persyaratan sebelum memakai rating transaksi.'):technical?tr('Price indicators only; no fundamental fair value.','Indikator harga saja; tanpa nilai wajar fundamental.'):conditional?tr('Model-implied signal; read assumptions and limitations.','Sinyal dari model; baca asumsi dan keterbatasan.'):tr('Forecasts and peer comparability remain model assumptions.','Proyeksi dan kesebandingan tetap asumsi model.')}<small>${esc((r.quality?.checks||[]).slice(0,2).map(x=>lang==='id'?x.id:x.en).join(' '))}</small></div><button data-view="integrity">${blocked?tr('Resolve requirements','Lihat persyaratan'):tr('Inspect basis','Periksa dasar')} ↗</button></div>`;}

function appendSensitivityReport(doc){const matrix=sensitivityMatrix(c,a,r),rows=tornado(c,a,r);doc.addPage();doc.setFont('helvetica','bold');doc.setFontSize(17);doc.text('Sensitivity & valuation drivers',18,24);doc.setFont('helvetica','normal');doc.setFontSize(9);let y=36;const add=text=>{const lines=doc.splitTextToSize(String(text),174);if(y+lines.length*4>272){doc.addPage();y=24;}doc.text(lines,18,y);y+=lines.length*4+4;};if(!matrix.available){add(matrix.reason);return;}add(matrix.description);add(`${matrix.rowLabel} (rows) / ${matrix.columnLabel} (columns). Base fair value: ${rp(r.fair)}.`);const cell=v=>matrix.kind==='relative'?fmt(v,2)+'x':pct(v);add('Columns: '+matrix.columnValues.map(cell).join(' | '));matrix.values.forEach((row,i)=>add(cell(matrix.rowValues[i])+': '+row.map(v=>Number.isFinite(v)?fmt(v):'unavailable').join(' | ')));add('One driver at a time; lower/higher refer to assumptions, not valuation direction. Blue: lower input; orange: higher input.');if(y+rows.length*11+20>272){doc.addPage();y=25;}const max=Math.max(1e-9,...rows.map(d=>d.impact)),center=133,scale=47/max;for(const d of rows){doc.setFontSize(8);doc.text(d.en+' '+d.shock,18,y+4);doc.setDrawColor(150,160,170);doc.line(center,y,center,y+9);for(const [value,offset,color]of [[d.low,0,[45,132,210]],[d.high,4.5,[220,146,28]]]){if(!Number.isFinite(value))continue;const change=(value-r.fair)*scale;doc.setFillColor(...color);doc.rect(center+Math.min(0,change),y+offset,Math.max(.2,Math.abs(change)),3,'F');}doc.text(fmt(d.impact),190,y+4,{align:'right'});y+=11;}y+=7;doc.setFontSize(9);for(const d of rows)add(`${d.en} (${d.shock}): lower-input fair ${rp(d.low)} / higher-input fair ${rp(d.high)}.`);}

function appendEvidenceReport(doc){doc.addPage();doc.setFont('helvetica','bold');doc.setFontSize(18);doc.text('Data evidence and recommendation policy',18,24);doc.setFont('helvetica','normal');doc.setFontSize(9);let y=37;const add=s=>{const lines=doc.splitTextToSize(String(s),174);if(y+lines.length*4>272){doc.addPage();y=24;}doc.text(lines,18,y);y+=lines.length*4+4;};add(`Status ${r.quality?.status||'UNVERIFIED'} / Recommendation ${r.recommendation} / Basis ${c.periodBasis||'ANNUAL'} ${c.period}`);if(c.balanceCheck)add(`Balance-sheet presentation: separately deducted funds ${(c.balanceCheck.presentation||[]).join(', ')||'none / already included in liabilities'}; residual ${fmt(c.balanceCheck.residual,3)} IDR bn; tolerance ${fmt(c.balanceCheck.tolerance,3)}. No balancing plug; fund subtotals are not counted twice.`);add(`Verified method inputs ${r.quality?.verified||0}/${r.quality?.total||0}. This measures source support, not investment confidence.`);for(const reason of r.quality?.reasons||[])add(reason);add('Source hierarchy: compatible primary facts take precedence. Differences above 1% stay flagged. Different EBITDA definitions, annual/YTD periods and currencies are not averaged. Mirrored issuer documents count as one origin.');for(const [basis,rows]of [['Active',c.evidence?.rows||[]],['Annual reference',c.evidence?.annualRows||[]]]){add(basis);for(const row of rows){add(`${row.field}: ${fmt(row.selected,3)} IDR bn / ${row.displayStatus||row.status} / ${row.sourceId||'unavailable'}; ${row.reason||''}`);for(const o of row.observations)add(`${o.sourceId}: ${o.value} ${o.currency} ${o.unit}; ${o.period}; ${o.definition}; ${o.locator}; published ${o.publishedAt||'unknown'}; retrieved ${o.retrievedAt||'unknown'}; ${o.url||'manual input'}`);}}for(const attempt of c.sourceAttempts||[])add(`${attempt.source}: ${attempt.status}; ${attempt.message}`);if(c.periodBasis==='TTM'){add('TTM = prior annual + current YTD - prior comparable YTD. No quarterly multiplication. Missing annual-only fields are not carried forward.');for(const o of c.observations||[])if(o.components)add(`${o.field}: `+o.components.map(x=>`${x.period}: ${x.value}`).join(' + / - '));}}


function appendPeerReport(doc){if(!(r.relative?.peers||[]).length)return;doc.addPage();doc.setFont('helvetica','bold');doc.setFontSize(18);doc.text('Peer evidence and scenario exhibits',18,24);doc.setFont('helvetica','normal');doc.setFontSize(9);let y=37;const add=s=>{const lines=doc.splitTextToSize(String(s),174);if(y+lines.length*4>272){doc.addPage();y=24;}doc.text(lines,18,y);y+=lines.length*4+4;};for(const p of r.relative.peers){add(`${p.ticker} / ${p.subIndustry||p.industry||p.sector} / ${p.period}: price ${p.price}; shares bn ${p.shares}; parent profit bn ${p.netIncome??'unavailable'}; equity bn ${p.bookEquity??'unavailable'}; EBITDA bn ${p.ebitda??'unavailable'}.`);for(const leg of r.relative.legs.filter(x=>x.price>0)){const key=leg.metric==='pe'?'netIncome':leg.metric==='pb'?'bookEquity':leg.metric==='evSales'?'revenue':'ebitda';const row=p.evidence?.rows?.find(x=>x.field===key),o=row?.observations?.find(x=>x.sourceType==='primary')||row?.observations?.[0];add(`${leg.metric} denominator: ${row?.status||'unverified'}; ${o?.locator||'source mapping unavailable'}; ${o?.url||p.source||'source unavailable'}`);}}add(`Deterministic scenarios: bear ${rp(r.scenarios.bear)} / base ${rp(r.scenarios.base)} / bull ${rp(r.scenarios.bull)}. ${scenarioDescription()} These are analyst shocks, not confidence limits.`);
 const prices=(c.prices||[]).filter(x=>Number.isFinite(x.close));if(prices.length>3){doc.addPage();doc.setFontSize(16);doc.text('Observed market price history',18,25);doc.setFontSize(9);doc.text(`${prices[0].date} to ${prices.at(-1).date}; IDR/share; public price feed`,18,35);const min=Math.min(...prices.map(x=>x.close)),max=Math.max(...prices.map(x=>x.close)),x=i=>22+i/(prices.length-1)*168,py=v=>160-(v-min)/(max-min||1)*105;doc.setDrawColor(180,190,200);doc.line(22,55,22,162);doc.line(22,162,190,162);doc.setDrawColor(210,130,15);for(let i=1;i<prices.length;i++)doc.line(x(i-1),py(prices[i-1].close),x(i),py(prices[i].close));doc.setTextColor(40,55,65);doc.text(fmt(max),22,51);doc.text(fmt(min),22,171);doc.text('Observed prices only. No historical fair value or future trading-price path is implied.',18,185);}}

async function boot(){render();try{const results=await Promise.all([getJSON('/data/universe.json'),getJSON('/data/catalog.json'),getJSON('/data/coverage.json'),getJSON('/data/ticker-prices.json').catch(()=>({}))]);[universe,catalog]=results;coverage=results[2].issuers||[];tickerHistory=results[3].prices||{};const query=new URL(location.href).searchParams,caseId=query.get('case'),archived=['BMRI-2026-10-25','RECOVERY-DEMO'].includes(caseId)?await getJSON('/data/cases/'+caseId+'.json'):null,ticker=(query.get('ticker')||'BBCA').trim().toUpperCase().replace(/\.JK$/,'');if(!/^[A-Z0-9]{4}$/.test(ticker))throw Error('Enter a four-character IDX ticker in the URL.');const first=archived?{...archived.company,archivedCase:archived.caseId}:await getJSON('/api/snapshot/'+ticker);if(!first.prices?.length){try{const bootstrap=await getJSON('/data/bootstrap.json');if(bootstrap.ticker===first.ticker)first.prices=bootstrap.prices;}catch{}}if(archived){mcConfig=normalizeSimulation(archived.simulation);mcCount=mcConfig.count;mcSeed=mcConfig.seed;}setCompany(first,archived?.assumptions,{historical:!!archived});render();if(archived)notify(archived.company.mode==='demo'?tr('Synthetic recovery example: fictional inputs for testing; not an issuer valuation.','Contoh pemulihan sintetis: input fiktif untuk pengujian; bukan valuasi emiten.'):tr('Archived BMRI case: source and valuation dates are fixed. Refresh explicitly to use new data.','Kasus arsip BMRI: tanggal sumber dan valuasi tetap. Pilih perbarui untuk data baru.'));(async()=>{let cursor=null;do{const updates=await getJSON('/api/updates'+(cursor?'?cursor='+encodeURIComponent(cursor):''));for(const company of updates.companies||[])updateCoverage(company);cursor=updates.cursor;}while(cursor);render();})().catch(()=>{});}catch(e){c=null;$('#app').innerHTML=`<div class="app-loading"><div class="loading-mark"><img src="/logo.png" alt="RALVEN logo"></div><b>RALVEN</b><strong>${tr('Research data unavailable','Data riset belum tersedia')}</strong><span>${tr('No recommendation was generated. Reload to retry the source snapshot.','Belum ada rekomendasi. Muat ulang untuk mencoba snapshot sumber.')}</span><details><summary>${tr('Connection details','Rincian koneksi')}</summary><p>${esc(e.message)}</p></details><button id="retry-data">${tr('Reload data','Muat ulang data')}</button><a href="mailto:yusufzaakaria@gmail.com">yusufzaakaria@gmail.com</a></div>`;$('#retry-data').onclick=()=>location.reload();}}



const researchControls=researchController({
 get:()=>({c,a,r,researchState,busy,simulation:{...mcConfig,count:mcCount,seed:mcSeed}}),
 actions,issuerState,persist:persistResearch,render,recalc,getJSON,notify,tr,saveBlob,setCompany,updateCoverage,
 setAssumptions:value=>{a=value;},
 setSimulation:value=>{mcConfig=value;mcCount=value.count;mcSeed=value.seed;},
 setBusy:value=>{busy=value;},
 setDirectory:value=>{universe=value;for(const p of value.issuers)if(!coverage.some(x=>x.ticker===p.ticker))coverage.push({...p,recommendation:'WAIT',basis:'UNRATED',decisionKind:'DATA',reason:'New directory record; open issuer to retrieve source data.'});},
 rescreenPeers:()=>{c.peers=selectPeers({...c,peers:c.peerUniverse});},
 toggleTicker:()=>{tickerPaused=!tickerPaused;localStorage.setItem('ralven-ticker-paused',String(tickerPaused));render();},
 sortDirection:()=>{sortDirection*=-1;render();}
});
function bindResearch(){researchControls.bind();}
boot();
